using NetArchTest.Rules;

namespace PaymentAuthorization.IntegrationTest.Architecture;

/// <summary>
/// Guards the Clean Architecture layering: Domain and Application must stay free of
/// technical/framework detail, and dependencies must only point inward.
/// This is a CI gate, not part of the fast per-save suite.
/// </summary>
public class LayerBoundaryTests
{
    private const string DomainNamespace = "PaymentAuthorization.Domain";
    private const string ApplicationNamespace = "PaymentAuthorization.Application";
    private const string InfrastructureNamespace = "PaymentAuthorization.Infrastructure";

    [Fact]
    public void Domain_should_not_depend_on_application_or_infrastructure()
    {
        var result = Types.InAssembly(typeof(Domain.Money).Assembly)
            .That()
            .ResideInNamespace(DomainNamespace)
            .ShouldNot()
            .HaveDependencyOnAny(ApplicationNamespace, InfrastructureNamespace)
            .GetResult();

        Assert.True(result.IsSuccessful, Describe(result));
    }

    [Fact]
    public void Application_should_not_depend_on_infrastructure()
    {
        var result = Types.InAssembly(typeof(Application.AuthorizePayment).Assembly)
            .That()
            .ResideInNamespace(ApplicationNamespace)
            .ShouldNot()
            .HaveDependencyOnAny(InfrastructureNamespace)
            .GetResult();

        Assert.True(result.IsSuccessful, Describe(result));
    }

    [Fact]
    public void Domain_should_only_depend_on_domain_and_the_language_core()
    {
        // Allow-list, not a deny-list: forbidding only the other layers would let any
        // framework or I/O client slip through as long as it isn't "Application"/"Infrastructure".
        var result = Types.InAssembly(typeof(Domain.Money).Assembly)
            .That()
            .ResideInNamespace(DomainNamespace)
            .Should()
            .OnlyHaveDependenciesOn(DomainNamespace, "System")
            .GetResult();

        Assert.True(result.IsSuccessful, Describe(result));
    }

    [Fact]
    public void Application_should_only_depend_on_application_domain_and_the_language_core()
    {
        var result = Types.InAssembly(typeof(Application.AuthorizePayment).Assembly)
            .That()
            .ResideInNamespace(ApplicationNamespace)
            .Should()
            .OnlyHaveDependenciesOn(ApplicationNamespace, DomainNamespace, "System")
            .GetResult();

        Assert.True(result.IsSuccessful, Describe(result));
    }

    private static string Describe(TestResult result) =>
        result.IsSuccessful
            ? string.Empty
            : $"Violations: {string.Join(", ", result.FailingTypeNames ?? [])}";
}

